// GRE Vocabulary Database — Part 1 (A-D)
// Sources: Manhattan Prep, Barron's, Magoosh combined & deduplicated
const VOCAB_DATA_1 = [
  {word:"aberrant",partOfSpeech:"adjective",definition:"departing from the accepted or normal standard; deviating from the usual course",difficulty:2,mnemonic:"'A BEAR RANT' — imagine a bear ranting and raving in a library. That's definitely not normal behavior!",etymology:"Latin 'aberrare' = to wander away (ab- 'away' + errare 'to wander, err')",exampleSentence:"The aberrant test results prompted the scientist to recheck her experimental procedures.",synonyms:["anomalous","deviant","atypical","irregular"],antonyms:["normal","typical","standard"],confusedWith:["abhorrent"],tags:["behavior","science"]},
  {word:"abjure",partOfSpeech:"verb",definition:"to formally reject or renounce a belief, cause, or claim",difficulty:3,mnemonic:"'AB-JURY' — imagine standing before a jury and swearing to give up your old ways forever.",etymology:"Latin 'abjurare' = to deny on oath (ab- 'away' + jurare 'to swear')",exampleSentence:"After the scandal, the politician publicly abjured his previous position on the issue.",synonyms:["renounce","repudiate","recant","forswear"],antonyms:["embrace","adopt","uphold"],confusedWith:["adjure"],tags:["formal","legal"]},
  {word:"abnegation",partOfSpeech:"noun",definition:"the act of renouncing or rejecting something; self-denial",difficulty:3,mnemonic:"'AB-NEGATION' — contains NEGATE. You're negating your own desires, saying NO to yourself.",etymology:"Latin 'abnegare' = to refuse, deny (ab- 'away' + negare 'to deny')",exampleSentence:"Her abnegation of personal comfort in favor of helping others earned widespread admiration.",synonyms:["renunciation","self-denial","abstinence"],antonyms:["indulgence","self-gratification"],confusedWith:["negation"],tags:["character","virtue"]},
  {word:"abscond",partOfSpeech:"verb",definition:"to leave hurriedly and secretly, typically to escape detection or arrest",difficulty:2,mnemonic:"'AB-SCOND' — sounds like 'absent + gone.' They absconded — they're absent because they're gone!",etymology:"Latin 'abscondere' = to hide away (abs- 'away' + condere 'to store, hide')",exampleSentence:"The treasurer absconded with the company's funds before anyone noticed the discrepancy.",synonyms:["flee","escape","bolt","decamp"],antonyms:["remain","stay","appear"],confusedWith:[],tags:["action","crime"]},
  {word:"abstain",partOfSpeech:"verb",definition:"to restrain oneself from doing or enjoying something",difficulty:1,mnemonic:"'ABS-TAIN' — to get great ABS, you must ABSTAIN from junk food. Self-control!",etymology:"Latin 'abstinere' = to hold back (abs- 'from' + tenere 'to hold')",exampleSentence:"Several committee members chose to abstain from voting on the controversial proposal.",synonyms:["refrain","forbear","desist"],antonyms:["indulge","partake","consume"],confusedWith:["obtain"],tags:["behavior","self-control"]},
  {word:"abstruse",partOfSpeech:"adjective",definition:"difficult to understand; obscure",difficulty:2,mnemonic:"'AB-STRUCE' — sounds like 'abstract + obtuse.' Something so abstract and obtuse that nobody gets it.",etymology:"Latin 'abstrusus' = hidden, concealed (abs- 'away' + trudere 'to push')",exampleSentence:"The professor's abstruse lecture on quantum mechanics left most students bewildered.",synonyms:["arcane","esoteric","recondite","opaque"],antonyms:["clear","obvious","straightforward"],confusedWith:["obtuse","abstract"],tags:["difficulty","academic"]},
  {word:"accolade",partOfSpeech:"noun",definition:"an award or privilege granted as a special honor; praise",difficulty:1,mnemonic:"'A-COLA-ADE' — imagine winning a lifetime supply of your favorite drink as a prize. What an accolade!",etymology:"French 'accolade' = an embrace, from Latin 'ad' + 'collum' (neck) — originally the embrace given when knighting someone",exampleSentence:"The film received numerous accolades, including three Academy Award nominations.",synonyms:["honor","award","tribute","commendation"],antonyms:["criticism","censure","rebuke"],confusedWith:[],tags:["recognition","positive"]},
  {word:"acerbic",partOfSpeech:"adjective",definition:"sharp and forthright in speech or manner; harsh or severe",difficulty:2,mnemonic:"'A-HERB-IC' — like biting into a SOUR herb. Acerbic comments leave a bitter taste.",etymology:"Latin 'acerbus' = sour, harsh (from 'acer' = sharp)",exampleSentence:"The critic was known for her acerbic wit, which could reduce even confident authors to silence.",synonyms:["caustic","mordant","sardonic","trenchant"],antonyms:["mild","gentle","sweet","kind"],confusedWith:["acidic"],tags:["speech","criticism"]},
  {word:"acrimony",partOfSpeech:"noun",definition:"bitterness or ill feeling in speech or manner",difficulty:2,mnemonic:"'ACRI-MONEY' — imagine a bitter divorce fight over MONEY, with ACID words flying. ACRID + MONEY = bitter argument about cash.",etymology:"Latin 'acrimonia' = sharpness (from 'acer' = sharp, pungent)",exampleSentence:"The acrimony between the two political rivals was evident in every debate.",synonyms:["bitterness","animosity","rancor","hostility"],antonyms:["goodwill","harmony","friendliness"],confusedWith:["matrimony"],tags:["conflict","emotion"]},
  {word:"acumen",partOfSpeech:"noun",definition:"the ability to make good judgments and quick decisions, typically in a particular domain",difficulty:2,mnemonic:"'A-CUTE-MEN' — imagine a group of cute, sharp-minded men who make brilliant business decisions. Acute + Men = sharp people.",etymology:"Latin 'acumen' = a point, sharpness (from 'acuere' = to sharpen)",exampleSentence:"Her financial acumen allowed her to turn a small investment into a substantial fortune.",synonyms:["shrewdness","astuteness","sagacity","perspicacity"],antonyms:["ignorance","stupidity","obtuseness"],confusedWith:[],tags:["intelligence","business"]},
  {word:"adamant",partOfSpeech:"adjective",definition:"refusing to be persuaded or to change one's mind; unyielding",difficulty:1,mnemonic:"'ADAM-ANT' — imagine an ant named Adam who absolutely REFUSES to move from your picnic blanket. Stubborn as Adam the ant!",etymology:"Greek 'adamas' = unconquerable, hard (a- 'not' + daman 'to tame') — originally referred to diamond or very hard metal",exampleSentence:"Despite pressure from her colleagues, she remained adamant that the project needed more testing.",synonyms:["resolute","unyielding","inflexible","immovable"],antonyms:["flexible","yielding","compliant"],confusedWith:[],tags:["character","determination"]},
  {word:"admonish",partOfSpeech:"verb",definition:"to warn or reprimand someone firmly; to urge seriously",difficulty:1,mnemonic:"'AD-MONSTER' — imagine a teacher who becomes a MONSTER in the AD (advertisement) when students misbehave, wagging her finger.",etymology:"Latin 'admonere' = to advise, warn (ad- 'to' + monere 'to warn')",exampleSentence:"The judge admonished the witness to answer the questions truthfully.",synonyms:["reprimand","rebuke","chide","caution"],antonyms:["praise","commend","applaud"],confusedWith:["administer"],tags:["authority","correction"]},
  {word:"adulterate",partOfSpeech:"verb",definition:"to make something poorer in quality by adding another substance",difficulty:2,mnemonic:"'ADULT-ERATE' — when you become an ADULT, your pure childhood joy gets 'mixed' with worries and stress. Corrupted!",etymology:"Latin 'adulterare' = to corrupt (from 'adulter' = adulterous, impure)",exampleSentence:"The company was fined for adulterating its products with cheaper, inferior ingredients.",synonyms:["contaminate","taint","debase","dilute"],antonyms:["purify","refine","enhance"],confusedWith:[],tags:["quality","corruption"]},
  {word:"aesthetic",partOfSpeech:"adjective",definition:"concerned with beauty or the appreciation of beauty; giving or designed to give pleasure through beauty",difficulty:1,mnemonic:"'A-ESTHETIC' — think of going to a gallery. Art gives you an 'A' in beauty appreciation. Aesthetics = the study of beauty.",etymology:"Greek 'aisthētikos' = perceptive (from 'aisthanesthai' = to perceive)",exampleSentence:"The building's aesthetic appeal masks its poor structural design.",synonyms:["artistic","visual","tasteful","pleasing"],antonyms:["unattractive","ugly","unsightly"],confusedWith:["ascetic"],tags:["art","beauty"]},
  {word:"affable",partOfSpeech:"adjective",definition:"friendly, good-natured, and easy to talk to",difficulty:2,mnemonic:"'A-FABLE' — someone so friendly, they're like a character from A FABLE — warm, approachable, and easy to talk to.",etymology:"Latin 'affabilis' = easy to speak to (ad- 'to' + fari 'to speak')",exampleSentence:"The affable shopkeeper knew every customer by name and always had a smile ready.",synonyms:["amiable","genial","cordial","approachable"],antonyms:["unfriendly","aloof","hostile","surly"],confusedWith:["affectionate"],tags:["personality","positive"]},
  {word:"aggrandize",partOfSpeech:"verb",definition:"to increase the power, status, or wealth of; to make appear greater",difficulty:2,mnemonic:"'A-GRAND-IZE' — to make something GRAND. Self-aggrandize = make yourself look GRAND and important.",etymology:"French 'agrandir' = to make larger (from Latin 'grandis' = large)",exampleSentence:"The dictator used propaganda to aggrandize his image among the populace.",synonyms:["enhance","elevate","magnify","exalt"],antonyms:["diminish","belittle","humble","reduce"],confusedWith:[],tags:["power","status"]},
  {word:"alacrity",partOfSpeech:"noun",definition:"brisk and cheerful readiness; eagerness",difficulty:2,mnemonic:"'A-LACK-RITY' — there's A LACK of laziness in this person! They jump up with cheerful eagerness to help.",etymology:"Latin 'alacritas' = liveliness, eagerness (from 'alacer' = lively, eager)",exampleSentence:"She accepted the challenging assignment with alacrity, eager to prove her abilities.",synonyms:["eagerness","enthusiasm","willingness","promptness"],antonyms:["reluctance","apathy","hesitation"],confusedWith:["clarity"],tags:["attitude","positive"]},
  {word:"amalgamate",partOfSpeech:"verb",definition:"to combine or unite to form one organization or structure; to merge",difficulty:2,mnemonic:"'A-MALL-GAME-ATE' — imagine A MALL where every store merges into one giant GAME store. Everything combined!",etymology:"Medieval Latin 'amalgamare' — originally an alchemical term for mixing mercury with other metals",exampleSentence:"The two rival companies decided to amalgamate to better compete in the global market.",synonyms:["merge","combine","consolidate","fuse"],antonyms:["separate","divide","split"],confusedWith:[],tags:["organization","change"]},
  {word:"ambiguous",partOfSpeech:"adjective",definition:"open to more than one interpretation; unclear or inexact",difficulty:1,mnemonic:"'AMBI-GUOUS' — AMBI means 'both' (like ambidextrous = both hands). Ambiguous = could go BOTH ways in meaning.",etymology:"Latin 'ambiguus' = doubtful (from 'ambigere' = to go around, waver; ambi- 'both' + agere 'to drive')",exampleSentence:"The contract's ambiguous language led to a protracted legal dispute between the parties.",synonyms:["vague","equivocal","unclear","nebulous"],antonyms:["clear","unambiguous","explicit","definite"],confusedWith:["ambivalent"],tags:["language","meaning"]},
  {word:"ambivalent",partOfSpeech:"adjective",definition:"having mixed feelings or contradictory ideas about something",difficulty:1,mnemonic:"'AMBI-VALENT' — AMBI (both) + VALENT (value). You VALUE BOTH sides equally, so you can't decide!",etymology:"German 'Ambivalenz' coined by Swiss psychiatrist Bleuler: Latin 'ambi-' (both) + 'valentia' (strength)",exampleSentence:"She felt ambivalent about accepting the job offer — excited about the role but reluctant to relocate.",synonyms:["uncertain","conflicted","torn","undecided"],antonyms:["certain","decisive","unequivocal"],confusedWith:["ambiguous","indifferent"],tags:["emotion","decision"]},
  {word:"ameliorate",partOfSpeech:"verb",definition:"to make something bad or unsatisfactory better; to improve",difficulty:2,mnemonic:"'A-MEAL-IORATE' — A good MEAL can make any bad day better. Food ameliorates your mood!",etymology:"Latin 'ameliorare' = to make better (from 'melior' = better)",exampleSentence:"The new policies were designed to ameliorate the living conditions in underserved neighborhoods.",synonyms:["improve","enhance","better","alleviate"],antonyms:["worsen","aggravate","deteriorate","exacerbate"],confusedWith:["meliorate"],tags:["improvement","positive"]},
  {word:"anachronism",partOfSpeech:"noun",definition:"a thing belonging to a period other than that in which it exists; something out of its proper time",difficulty:2,mnemonic:"'ANA-CHRON-ISM' — CHRON = time (like chronological). Something that's 'against' (ana-) the proper TIME period, like seeing a smartphone in a medieval movie.",etymology:"Greek 'anachronismos' (ana- 'backward' + chronos 'time')",exampleSentence:"The presence of a wristwatch in the period film was a glaring anachronism.",synonyms:["throwback","relic","archaism"],antonyms:[],confusedWith:[],tags:["time","history"]},
  {word:"analogous",partOfSpeech:"adjective",definition:"comparable in certain respects, typically in a way that makes clearer the nature of the things compared",difficulty:2,mnemonic:"'ANALOG-OUS' — like an ANALOG clock compared to a digital one. Different but SIMILAR in function.",etymology:"Greek 'analogos' = proportionate (ana- 'upon, according to' + logos 'ratio')",exampleSentence:"The structure of an atom is roughly analogous to a miniature solar system.",synonyms:["comparable","similar","parallel","corresponding"],antonyms:["different","dissimilar","unlike"],confusedWith:["homologous"],tags:["comparison","logic"]},
  {word:"anomalous",partOfSpeech:"adjective",definition:"deviating from what is standard, normal, or expected",difficulty:2,mnemonic:"'A-NO-MALOUS' — it's 'NOT NORMAL' — say it fast: 'a-not-malos.' Something that breaks the pattern.",etymology:"Greek 'anomalos' = uneven, irregular (an- 'not' + homalos 'even')",exampleSentence:"The anomalous weather patterns have puzzled meteorologists for months.",synonyms:["abnormal","atypical","irregular","deviant"],antonyms:["normal","typical","regular","expected"],confusedWith:["anonymous"],tags:["pattern","science"]},
  {word:"antipathy",partOfSpeech:"noun",definition:"a deep-seated feeling of dislike; aversion",difficulty:2,mnemonic:"'ANTI-PATHY' — ANTI = against, PATHY = feeling (like sympathy/empathy). AGAINST-FEELING = strong dislike.",etymology:"Greek 'antipatheia' (anti- 'against' + pathos 'feeling')",exampleSentence:"His antipathy toward modern art was well known among his colleagues in the department.",synonyms:["aversion","hostility","animosity","dislike"],antonyms:["sympathy","affection","fondness","rapport"],confusedWith:["apathy"],tags:["emotion","negative"]},
  {word:"apathy",partOfSpeech:"noun",definition:"lack of interest, enthusiasm, or concern; indifference",difficulty:1,mnemonic:"'A-PATHY' — A = without, PATHY = feeling. Literally WITHOUT FEELING. Too bored to care.",etymology:"Greek 'apatheia' = without feeling (a- 'without' + pathos 'feeling, emotion')",exampleSentence:"Voter apathy led to the lowest election turnout in decades.",synonyms:["indifference","disinterest","lethargy","passivity"],antonyms:["enthusiasm","passion","concern","interest"],confusedWith:["antipathy","sympathy","empathy"],tags:["emotion","negative"]},
  {word:"appease",partOfSpeech:"verb",definition:"to pacify or calm someone by acceding to their demands; to relieve or satisfy",difficulty:1,mnemonic:"'A-PEACE' — to bring A PEACE. You appease someone to make PEACE with them.",etymology:"Old French 'apaisier' = to bring to peace (a- 'to' + pais 'peace')",exampleSentence:"The company offered a full refund to appease the dissatisfied customers.",synonyms:["pacify","placate","mollify","conciliate"],antonyms:["aggravate","provoke","antagonize","enrage"],confusedWith:[],tags:["conflict","diplomacy"]},
  {word:"approbation",partOfSpeech:"noun",definition:"approval or praise; official recognition",difficulty:3,mnemonic:"'APPRO-BATION' — contains APPROVE. Approbation = strong APPROVAL. Think 'approval + ovation' = applause of approval.",etymology:"Latin 'approbatio' = approval (from 'approbare' = to approve; ad- 'to' + probare 'to test, prove')",exampleSentence:"The plan received the approbation of the board and was immediately put into action.",synonyms:["approval","endorsement","commendation","sanction"],antonyms:["disapproval","condemnation","censure"],confusedWith:["approbrium","appropriation"],tags:["approval","formal"]},
  {word:"arduous",partOfSpeech:"adjective",definition:"involving or requiring strenuous effort; difficult and tiring",difficulty:1,mnemonic:"'ARE-DO-US' — 'ARE you going to DO this with US?' they asked about climbing the steep mountain. It's going to be HARD!",etymology:"Latin 'arduus' = steep, difficult (related to 'altus' = high)",exampleSentence:"The arduous trek through the mountain pass tested even the most experienced hikers.",synonyms:["strenuous","laborious","grueling","demanding"],antonyms:["easy","effortless","simple"],confusedWith:[],tags:["difficulty","effort"]},
  {word:"artful",partOfSpeech:"adjective",definition:"clever or skillful, especially in a crafty or cunning way",difficulty:1,mnemonic:"'ART-FULL' — full of ART and craft. Can mean skillfully creative OR cunningly deceptive — like a con artist!",etymology:"English 'art' + '-ful' — originally meaning 'displaying art or skill'",exampleSentence:"The diplomat's artful negotiation prevented the talks from collapsing entirely.",synonyms:["cunning","shrewd","crafty","ingenious"],antonyms:["artless","naive","guileless","candid"],confusedWith:["artless","artistic"],tags:["intelligence","deception"]},
  {word:"ascetic",partOfSpeech:"adjective",definition:"characterized by severe self-discipline and abstention from all forms of indulgence",difficulty:2,mnemonic:"'A-SET-IC' — imagine someone who SET their life to the simplest mode. No luxuries, no indulgence. Don't confuse with AESTHETIC (beauty)!",etymology:"Greek 'asketikos' = rigorously self-disciplined (from 'askein' = to exercise, train)",exampleSentence:"The monk's ascetic lifestyle involved fasting, meditation, and sleeping on a bare floor.",synonyms:["austere","spartan","abstinent","self-denying"],antonyms:["indulgent","hedonistic","luxurious","sybaritic"],confusedWith:["aesthetic"],tags:["lifestyle","discipline"]},
  {word:"assuage",partOfSpeech:"verb",definition:"to make an unpleasant feeling less intense; to satisfy a desire or appetite",difficulty:2,mnemonic:"'A-SAUSAGE' — when you're hungry and upset, A SAUSAGE can calm your hunger and soothe your mood. Comfort food assuages!",etymology:"Old French 'assouagier' = to calm (from Latin 'ad-' + 'suavis' = sweet, pleasant)",exampleSentence:"Nothing could assuage her grief after the loss, though many friends tried.",synonyms:["relieve","ease","mitigate","alleviate","soothe"],antonyms:["aggravate","intensify","worsen","exacerbate"],confusedWith:["massage"],tags:["comfort","relief"]},
  {word:"audacious",partOfSpeech:"adjective",definition:"showing a willingness to take surprisingly bold risks; impudent",difficulty:1,mnemonic:"'AUDA-CIOUS' — sounds like 'AUDIO-CIOUS.' Imagine someone so bold they turn their AUDIO up to maximum in a library. Daring!",etymology:"Latin 'audax' = bold (from 'audere' = to dare)",exampleSentence:"The audacious rescue plan involved parachuting onto the roof of the building.",synonyms:["bold","daring","brazen","intrepid"],antonyms:["timid","cautious","meek","cowardly"],confusedWith:[],tags:["courage","character"]},
  {word:"austere",partOfSpeech:"adjective",definition:"severe or strict in manner or attitude; having no comforts or luxuries",difficulty:2,mnemonic:"'AUS-STEER' — imagine an AUSTRIAN STEER farmer. Life on the cold mountain farm is harsh, bare, and disciplined.",etymology:"Greek 'austeros' = severe, harsh (originally = making the tongue dry and rough)",exampleSentence:"The monastery's austere environment was designed to promote reflection and spiritual growth.",synonyms:["stern","severe","spartan","ascetic","stark"],antonyms:["luxurious","elaborate","indulgent","ornate"],confusedWith:["ascetic"],tags:["lifestyle","appearance"]},
  {word:"avarice",partOfSpeech:"noun",definition:"extreme greed for wealth or material gain",difficulty:2,mnemonic:"'AVA-RICE' — imagine a woman named AVA who hoards mountains of RICE, far more than she could ever eat. Pure greed!",etymology:"Latin 'avaritia' = greed (from 'avarus' = greedy, from 'avere' = to crave)",exampleSentence:"His avarice knew no bounds; even after amassing a fortune, he continued to exploit his workers.",synonyms:["greed","cupidity","rapacity","covetousness"],antonyms:["generosity","philanthropy","altruism"],confusedWith:[],tags:["money","vice"]},
  {word:"belie",partOfSpeech:"verb",definition:"to give a false impression of; to fail to reflect the true nature of",difficulty:2,mnemonic:"'BE-LIE' — to BE a LIE. Her calm face BELIED (was a lie about) her inner panic.",etymology:"Old English 'beleogan' = to deceive by lying (be- + lie)",exampleSentence:"Her cheerful demeanor belied the anxiety she was feeling about the upcoming exam.",synonyms:["contradict","misrepresent","disguise","negate"],antonyms:["reveal","confirm","reflect","expose"],confusedWith:["believe","betray"],tags:["deception","appearance"]},
  {word:"bellicose",partOfSpeech:"adjective",definition:"demonstrating aggression and willingness to fight",difficulty:2,mnemonic:"'BELLY-COSE' — imagine someone so aggressive they BELLY-bump you up close. Or think BELL + I + COSE: 'BELL rings, I go to war!'",etymology:"Latin 'bellicosus' = warlike (from 'bellum' = war — also in 'rebel', 'antebellum')",exampleSentence:"The bellicose rhetoric from both sides made diplomatic negotiations nearly impossible.",synonyms:["aggressive","combative","pugnacious","belligerent","warlike"],antonyms:["peaceful","pacific","conciliatory","dovish"],confusedWith:["belligerent"],tags:["conflict","aggression"]},
  {word:"benevolent",partOfSpeech:"adjective",definition:"well-meaning and kindly; generous in providing aid",difficulty:1,mnemonic:"'BENE-VOLENT' — BENE = good (like benefit), VOLENT = wishing (like voluntary). GOOD-WISHING person. A kind heart.",etymology:"Latin 'benevolens' = well-wishing (bene- 'well' + volens 'wishing', from 'velle' = to wish)",exampleSentence:"The benevolent donor funded scholarships for dozens of underprivileged students.",synonyms:["kind","charitable","philanthropic","altruistic"],antonyms:["malevolent","cruel","selfish","hostile"],confusedWith:["benign"],tags:["character","virtue"]},
  {word:"bolster",partOfSpeech:"verb",definition:"to support, strengthen, or prop up",difficulty:1,mnemonic:"'BOLSTER' — like a BOLSTER pillow that SUPPORTS your back. To bolster = to prop up and support.",etymology:"Old English/Dutch 'bolster' = a long, thick pillow used for support",exampleSentence:"The new evidence helped bolster the prosecution's case against the defendant.",synonyms:["support","strengthen","reinforce","buttress"],antonyms:["undermine","weaken","sabotage"],confusedWith:[],tags:["support","positive"]},
  {word:"bombastic",partOfSpeech:"adjective",definition:"high-sounding but with little meaning; inflated and pretentious in style",difficulty:2,mnemonic:"'BOMB-ASTIC' — like a BOMB of words! Loud, explosive speech that's all noise and no substance.",etymology:"From 'bombast' — originally meant cotton padding/stuffing, then figuratively 'padded, inflated language'",exampleSentence:"The senator's bombastic speech was full of grand promises but devoid of specific plans.",synonyms:["pompous","grandiloquent","turgid","inflated"],antonyms:["understated","modest","plain","humble"],confusedWith:["fantastic"],tags:["speech","negative"]},
  {word:"burgeon",partOfSpeech:"verb",definition:"to begin to grow or increase rapidly; to flourish",difficulty:2,mnemonic:"'BURGER-ON' — imagine burgers growing ON trees, multiplying rapidly. A burgeoning burger forest!",etymology:"Old French 'borjon' = a bud, shoot (related to budding and sprouting)",exampleSentence:"The tech industry continued to burgeon, creating thousands of new jobs every month.",synonyms:["flourish","thrive","proliferate","bloom","expand"],antonyms:["shrink","decline","wither","stagnate"],confusedWith:["burden"],tags:["growth","positive"]},
  {word:"cacophony",partOfSpeech:"noun",definition:"a harsh, discordant mixture of sounds",difficulty:2,mnemonic:"'CACO-PHONY' — CACO = bad (like 'caca'), PHONY = sound (like telephone). BAD SOUND = harsh noise.",etymology:"Greek 'kakophonia' (kakos 'bad' + phone 'voice, sound')",exampleSentence:"The cacophony of car horns and construction noise made it impossible to concentrate.",synonyms:["discord","dissonance","din","clamor"],antonyms:["harmony","euphony","melody"],confusedWith:["euphony"],tags:["sound","negative"]},
  {word:"cajole",partOfSpeech:"verb",definition:"to persuade someone to do something by sustained coaxing or flattery",difficulty:2,mnemonic:"'CA-JOLE' — imagine a person who is so JOLLY (JOLE) they charm you into doing anything. Sweet-talking you into it!",etymology:"French 'cajoler' = to coax, possibly from 'cage' (like coaxing a bird into a cage)",exampleSentence:"She managed to cajole her reluctant colleague into presenting at the conference.",synonyms:["coax","wheedle","persuade","sweet-talk"],antonyms:["bully","coerce","force","intimidate"],confusedWith:[],tags:["persuasion","social"]},
  {word:"calumny",partOfSpeech:"noun",definition:"the making of false and defamatory statements about someone; slander",difficulty:3,mnemonic:"'COLUMN-Y' — imagine a newspaper COLUMN full of LIES about you. That's calumny — false attacks on your character.",etymology:"Latin 'calumnia' = false accusation, trickery (from 'calvi' = to deceive)",exampleSentence:"The politician dismissed the accusations as calumny designed to derail her campaign.",synonyms:["slander","defamation","libel","vilification"],antonyms:["praise","commendation","eulogy"],confusedWith:["calamity"],tags:["reputation","legal"]},
  {word:"candor",partOfSpeech:"noun",definition:"the quality of being open and honest in expression; frankness",difficulty:1,mnemonic:"'CANDLE-OR' — a CANDLE reveals everything in the dark. Candor = shining light on the truth. No hiding.",etymology:"Latin 'candor' = whiteness, purity, sincerity (from 'candere' = to shine, glow white)",exampleSentence:"I appreciate your candor in telling me exactly what you thought of my proposal.",synonyms:["frankness","honesty","openness","directness"],antonyms:["deceit","dishonesty","guile","evasion"],confusedWith:["candid"],tags:["honesty","communication"]},
  {word:"capricious",partOfSpeech:"adjective",definition:"given to sudden and unaccountable changes of mood or behavior; unpredictable",difficulty:2,mnemonic:"'CAPRI-CIOUS' — like a goat (Capricorn/capra) jumping unpredictably from rock to rock. Or: weather on the island of CAPRI is notoriously changeable!",etymology:"Italian 'capriccio' = sudden shiver or whim (possibly from 'capra' = goat — goats jump unpredictably)",exampleSentence:"The capricious weather made it impossible to plan any outdoor activities.",synonyms:["fickle","volatile","mercurial","whimsical","erratic"],antonyms:["steadfast","constant","predictable","stable"],confusedWith:["arbitrary"],tags:["behavior","unpredictability"]},
  {word:"castigate",partOfSpeech:"verb",definition:"to reprimand someone severely; to criticize harshly",difficulty:2,mnemonic:"'CASTI-GATE' — imagine being scolded so badly at the CASTLE GATE that you can't enter. Harsh punishment at the gate!",etymology:"Latin 'castigare' = to purify, correct, punish (castus 'pure' + agere 'to drive')",exampleSentence:"The editorial castigated the government for its failure to respond to the humanitarian crisis.",synonyms:["reprimand","chastise","rebuke","lambaste","censure"],antonyms:["praise","commend","laud","extol"],confusedWith:["castrate"],tags:["criticism","punishment"]},
  {word:"caustic",partOfSpeech:"adjective",definition:"sarcastic in a scathing and bitter way; able to burn or corrode organic tissue",difficulty:2,mnemonic:"'CAUSE-TICK' — caustic words CAUSE a TICK of irritation. They burn! Like acid that corrodes, caustic words corrode relationships.",etymology:"Greek 'kaustikos' = capable of burning (from 'kaiein' = to burn)",exampleSentence:"Her caustic remarks about his presentation left him feeling humiliated in front of the team.",synonyms:["acerbic","mordant","scathing","corrosive","biting"],antonyms:["mild","gentle","kind","soothing"],confusedWith:["cosmic"],tags:["speech","criticism"]},
  {word:"chicanery",partOfSpeech:"noun",definition:"the use of trickery to achieve a political, financial, or legal purpose; deception",difficulty:3,mnemonic:"'CHICK-AN-ERY' — imagine a CHICK (baby chicken) who tricks all the farm animals out of their feed. Sneaky little trickster!",etymology:"French 'chicaner' = to quibble, use tricks (origin uncertain, possibly from medieval Latin 'cicanare')",exampleSentence:"The investigation revealed years of financial chicanery that had cost investors millions.",synonyms:["trickery","deception","subterfuge","duplicity","fraud"],antonyms:["honesty","integrity","transparency"],confusedWith:[],tags:["deception","legal"]},
  {word:"circumscribe",partOfSpeech:"verb",definition:"to restrict or limit; to draw a line around",difficulty:2,mnemonic:"'CIRCUM-SCRIBE' — CIRCUM = around (circumference), SCRIBE = write/draw. To draw a circle AROUND something = to limit its boundaries.",etymology:"Latin 'circumscribere' (circum- 'around' + scribere 'to write, draw')",exampleSentence:"Budget constraints circumscribed the scope of the research project significantly.",synonyms:["restrict","limit","confine","constrain","delimit"],antonyms:["expand","extend","free","liberate"],confusedWith:["prescribe","describe"],tags:["limitation","boundary"]},
  {word:"cogent",partOfSpeech:"adjective",definition:"clear, logical, and convincing in reasoning or argument",difficulty:2,mnemonic:"'CO-GENT' — imagine a CO-worker who is a real GENTleman — always making clear, convincing arguments politely.",etymology:"Latin 'cogent-' = compelling (from 'cogere' = to compel; co- 'together' + agere 'to drive')",exampleSentence:"The lawyer presented a cogent argument that swayed even the most skeptical jurors.",synonyms:["compelling","convincing","persuasive","forceful","logical"],antonyms:["unconvincing","weak","vague","muddled"],confusedWith:["coherent"],tags:["logic","argument"]},
  {word:"commensurate",partOfSpeech:"adjective",definition:"corresponding in size, extent, or degree; proportional",difficulty:2,mnemonic:"'CO-MEASURE-ATE' — to CO-MEASURE things. Commensurate means measured together = same proportion. Salary commensurate with experience.",etymology:"Latin 'commensuratus' (com- 'together' + mensurare 'to measure')",exampleSentence:"She expected a salary commensurate with her years of experience and qualifications.",synonyms:["proportional","corresponding","equivalent","comparable"],antonyms:["disproportionate","inadequate","unequal"],confusedWith:["commiserate"],tags:["proportion","comparison"]},
  {word:"compendium",partOfSpeech:"noun",definition:"a collection of concise but detailed information about a particular subject",difficulty:2,mnemonic:"'COMP-END-IUM' — a COMPrehensive summary that covers everything from start to END. A complete reference book.",etymology:"Latin 'compendium' = profit, saving, shortcut (from 'compendere' = to weigh together)",exampleSentence:"The professor recommended a compendium of essays on modern political theory.",synonyms:["collection","compilation","anthology","digest","summary"],antonyms:["expansion","elaboration"],confusedWith:["companion"],tags:["knowledge","reference"]},
  {word:"complaisant",partOfSpeech:"adjective",definition:"willing to please others; agreeably obliging",difficulty:3,mnemonic:"'COMPLY-SANT' — someone who COMPLIES with a pleasant SANT-a smile. Always happy to go along! (Don't confuse with complacent = smug satisfaction.)",etymology:"French 'complaisant' = pleasing (from 'complaire' = to please; Latin 'complacere')",exampleSentence:"The complaisant waiter accommodated every special request without a hint of annoyance.",synonyms:["obliging","accommodating","agreeable","deferential"],antonyms:["uncooperative","obstinate","defiant"],confusedWith:["complacent"],tags:["personality","social"]},
  {word:"concomitant",partOfSpeech:"adjective",definition:"naturally accompanying or associated; occurring alongside",difficulty:3,mnemonic:"'CON-COME-ITANT' — things that COME together, CON (with) each other. They're partners that always show up at the same time.",etymology:"Latin 'concomitari' = to accompany (con- 'together' + comitari 'to accompany', from 'comes' = companion)",exampleSentence:"Rapid urbanization brought concomitant problems of pollution and overcrowding.",synonyms:["accompanying","attendant","coexisting","concurrent"],antonyms:["unrelated","separate","independent"],confusedWith:[],tags:["relationship","academic"]},
  {word:"conciliatory",partOfSpeech:"adjective",definition:"intended or likely to placate or pacify; aimed at making peace",difficulty:2,mnemonic:"'COUNCIL-IATORY' — like a COUNCIL meeting where everyone tries to make peace. Conciliatory = peace-making.",etymology:"Latin 'conciliare' = to bring together, unite, win over (from 'concilium' = council)",exampleSentence:"After weeks of heated debate, the CEO adopted a conciliatory tone to restore team morale.",synonyms:["peaceable","appeasing","mollifying","placatory"],antonyms:["antagonistic","provocative","hostile","bellicose"],confusedWith:[],tags:["conflict","diplomacy"]},
  {word:"contentious",partOfSpeech:"adjective",definition:"causing or likely to cause an argument; controversial; given to arguing",difficulty:1,mnemonic:"'CONTENT-IOUS' — nobody is CONTENT, everybody is arguing! A contentious topic makes everyone upset and debating.",etymology:"Latin 'contentiosus' = quarrelsome (from 'contentio' = straining, contest; from 'contendere' = to strive)",exampleSentence:"Immigration policy remains one of the most contentious issues in modern politics.",synonyms:["controversial","disputed","argumentative","combative"],antonyms:["agreeable","uncontroversial","harmonious"],confusedWith:["content"],tags:["conflict","debate"]},
  {word:"contrite",partOfSpeech:"adjective",definition:"feeling or expressing remorse or penitence; affected by guilt",difficulty:2,mnemonic:"'CON-TRITE' — the CON (criminal) is TRITE (tired/worn down) from guilt. So sorry and worn out by remorse.",etymology:"Latin 'contritus' = worn out, ground down (from 'conterere' = to grind; con- 'together' + terere 'to rub')",exampleSentence:"He offered a contrite apology for his thoughtless remarks during the meeting.",synonyms:["remorseful","penitent","repentant","apologetic"],antonyms:["unrepentant","defiant","unapologetic","proud"],confusedWith:["trite"],tags:["emotion","guilt"]},
  {word:"convoluted",partOfSpeech:"adjective",definition:"extremely complex and difficult to follow; intricately twisted or coiled",difficulty:1,mnemonic:"'CON-VOLUTED' — imagine a story told by a CON artist with so many VOLUTEs (twists) that you can't follow the lies anymore.",etymology:"Latin 'convolutus' = rolled up (from 'convolvere' = to roll together; con- + volvere 'to roll')",exampleSentence:"The plot of the novel was so convoluted that readers often lost track of the storyline.",synonyms:["complicated","intricate","complex","tortuous","labyrinthine"],antonyms:["simple","straightforward","clear","direct"],confusedWith:[],tags:["complexity","description"]},
  {word:"copious",partOfSpeech:"adjective",definition:"abundant in supply or quantity; plentiful",difficulty:1,mnemonic:"'COPY-OUS' — imagine making so many COPIES that they overflow the room. COPIOUS = tons and tons of something.",etymology:"Latin 'copiosus' = plentiful (from 'copia' = abundance; co- 'together' + ops 'wealth')",exampleSentence:"She took copious notes during the lecture, filling three notebooks by the end.",synonyms:["abundant","plentiful","ample","profuse","bountiful"],antonyms:["scarce","meager","sparse","insufficient"],confusedWith:[],tags:["quantity","description"]},
  {word:"corroborate",partOfSpeech:"verb",definition:"to confirm or give support to a statement, theory, or finding",difficulty:2,mnemonic:"'CO-ROBO-RATE' — imagine two ROBOts who independently confirm the same finding. Their data CO-rroborates!",etymology:"Latin 'corroborare' = to strengthen (cor- 'together' + roborare 'to strengthen', from 'robur' = strength, oak)",exampleSentence:"The witness's testimony corroborated the evidence gathered by investigators.",synonyms:["confirm","verify","substantiate","validate","support"],antonyms:["contradict","refute","disprove","deny"],confusedWith:["collaborate"],tags:["evidence","proof"]},
  {word:"credulous",partOfSpeech:"adjective",definition:"having or showing too great a readiness to believe things; gullible",difficulty:2,mnemonic:"'CRED-ULOUS' — too much CRED (credit/belief). A credulous person gives CREDIT to everything, even obvious lies.",etymology:"Latin 'credulus' = easily believing (from 'credere' = to believe)",exampleSentence:"The credulous investors fell for the scam, trusting the con artist's elaborate promises.",synonyms:["gullible","naive","trusting","unsuspecting"],antonyms:["skeptical","cynical","incredulous","suspicious"],confusedWith:["incredible","incredulous"],tags:["judgment","personality"]},
  {word:"cursory",partOfSpeech:"adjective",definition:"hasty and therefore not thorough or detailed; superficial",difficulty:2,mnemonic:"'CURSOR-Y' — like moving your CURSOR quickly over a document without really reading it. A quick, surface-level glance.",etymology:"Latin 'cursorius' = of running (from 'cursor' = runner, from 'currere' = to run)",exampleSentence:"A cursory glance at the report revealed several significant errors in the data.",synonyms:["superficial","perfunctory","hasty","brief","casual"],antonyms:["thorough","meticulous","detailed","exhaustive"],confusedWith:[],tags:["effort","quality"]},
  {word:"daunt",partOfSpeech:"verb",definition:"to make someone feel intimidated or apprehensive",difficulty:1,mnemonic:"'DAUNT' — rhymes with HAUNT. Something that HAUNTS you and makes you scared to try. Daunting = intimidating.",etymology:"Old French 'danter' = to tame, subdue (from Latin 'domitare' = to tame, from 'domare')",exampleSentence:"The sheer volume of material to study would daunt even the most diligent student.",synonyms:["intimidate","discourage","dishearten","unnerve","dismay"],antonyms:["encourage","embolden","hearten","inspire"],confusedWith:["flaunt","jaunt"],tags:["emotion","fear"]},
  {word:"dearth",partOfSpeech:"noun",definition:"a scarcity or lack of something",difficulty:2,mnemonic:"'DEAR-TH' — when things become DEAR (expensive), it's because there's a scarciTH (scarcity) of them. Low supply = high price.",etymology:"Middle English 'derthe' = scarcity, famine (from 'dere' = precious, costly)",exampleSentence:"The dearth of qualified applicants forced the company to extend the hiring deadline.",synonyms:["scarcity","shortage","deficiency","paucity","lack"],antonyms:["abundance","surplus","plethora","excess"],confusedWith:["death"],tags:["quantity","lack"]},
  {word:"decorum",partOfSpeech:"noun",definition:"behavior in keeping with good taste and propriety; etiquette",difficulty:2,mnemonic:"'DECOR-UM' — good DÉCOR in a room shows taste. Good DECORUM in a person shows proper behavior and class.",etymology:"Latin 'decorum' = that which is proper (from 'decorus' = becoming, proper, from 'decor' = beauty, grace)",exampleSentence:"The students were expected to maintain decorum during the formal ceremony.",synonyms:["propriety","etiquette","dignity","respectability","protocol"],antonyms:["impropriety","rudeness","indecorum","boorishness"],confusedWith:["decoration"],tags:["behavior","social"]},
  {word:"deference",partOfSpeech:"noun",definition:"humble submission and respect; polite yielding to the opinion or wishes of another",difficulty:2,mnemonic:"'DEFER-ENCE' — you DEFER to someone when you show DEFERENCE. Like letting your elder speak first.",etymology:"French 'déférence' (from 'déférer' = to yield; Latin 'deferre' = to carry away, submit; de- 'away' + ferre 'to carry')",exampleSentence:"Out of deference to the host, the guests waited to be seated before beginning the meal.",synonyms:["respect","regard","submission","compliance","reverence"],antonyms:["disrespect","defiance","insolence","contempt"],confusedWith:["difference"],tags:["respect","social"]},
  {word:"delineate",partOfSpeech:"verb",definition:"to describe or portray something precisely; to outline or indicate",difficulty:2,mnemonic:"'DE-LINE-ATE' — draw a LINE around it to make it clear. Delineate = to mark out the boundaries precisely.",etymology:"Latin 'delineare' = to sketch out (de- 'completely' + lineare 'to draw a line', from 'linea' = line)",exampleSentence:"The report clearly delineated the responsibilities of each team member.",synonyms:["outline","describe","define","depict","demarcate"],antonyms:["confuse","obscure","blur"],confusedWith:["eliminate"],tags:["clarity","description"]},
  {word:"demur",partOfSpeech:"verb",definition:"to raise doubts or objections; to show reluctance",difficulty:2,mnemonic:"'DE-MURMUR' — you MURMUR your objections quietly but firmly. Not a loud protest, just a hesitant 'hmm, I'm not sure...'",etymology:"Old French 'demorer' = to linger, hesitate (from Latin 'demorari' = to delay; de- + morari 'to delay')",exampleSentence:"When asked to work overtime again, she demurred, citing family commitments.",synonyms:["object","protest","dissent","hesitate","balk"],antonyms:["agree","accept","consent","comply"],confusedWith:["demure"],tags:["disagreement","polite"]},
  {word:"denigrate",partOfSpeech:"verb",definition:"to criticize unfairly; to disparage or belittle",difficulty:2,mnemonic:"'DE-NEGATE' — to NEGATE someone's worth. To tear them down and make them seem worthless.",etymology:"Latin 'denigrare' = to blacken (de- 'completely' + nigrare 'to blacken', from 'niger' = black)",exampleSentence:"The opposition's attempts to denigrate her achievements only strengthened public support for her.",synonyms:["disparage","belittle","deprecate","malign","defame"],antonyms:["praise","extol","laud","exalt","acclaim"],confusedWith:["designate"],tags:["criticism","negative"]},
  {word:"deride",partOfSpeech:"verb",definition:"to express contempt for; to ridicule or mock",difficulty:2,mnemonic:"'DE-RIDE' — to take someone for a RIDE and laugh at them. They're the butt of the joke, being mocked.",etymology:"Latin 'deridere' = to ridicule (de- 'down' + ridere 'to laugh')",exampleSentence:"Critics derided the film as simplistic, but audiences loved it.",synonyms:["mock","ridicule","scorn","belittle","jeer"],antonyms:["praise","respect","admire","commend"],confusedWith:["derive"],tags:["contempt","mockery"]},
  {word:"derivative",partOfSpeech:"adjective",definition:"imitative of the work of another person, and usually disapproved of for that reason; not original",difficulty:1,mnemonic:"'DERIVE-ATIVE' — something DERIVED from something else, not original. A derivative movie = 'we've seen this before.'",etymology:"Latin 'derivare' = to lead or draw off water (de- 'away' + rivus 'stream')",exampleSentence:"The novel was criticized as derivative, borrowing heavily from several classic works.",synonyms:["imitative","unoriginal","secondary","borrowed"],antonyms:["original","innovative","creative","novel"],confusedWith:[],tags:["creativity","criticism"]},
  {word:"desiccate",partOfSpeech:"verb",definition:"to remove the moisture from something; to dry out completely",difficulty:3,mnemonic:"'DESERT-ICATE' — a DESERT desiccates everything. Imagine leaving fruit in a hot desert until it's bone dry.",etymology:"Latin 'desiccare' = to dry up (de- 'thoroughly' + siccare 'to dry', from 'siccus' = dry)",exampleSentence:"The prolonged drought desiccated the farmland, making cultivation impossible.",synonyms:["dehydrate","dry","parch","drain"],antonyms:["hydrate","moisten","saturate","soak"],confusedWith:["desecrate"],tags:["nature","process"]},
  {word:"desultory",partOfSpeech:"adjective",definition:"lacking a plan, purpose, or enthusiasm; occurring randomly or occasionally",difficulty:3,mnemonic:"'DE-SULTORY' — sounds like 'DE-RESULT-ORY.' With no direction, there will be NO RESULT. Aimless and random.",etymology:"Latin 'desultorius' = superficial (from 'desultor' = a circus rider who leaps from horse to horse — jumping randomly!)",exampleSentence:"The desultory conversation wandered from topic to topic without any clear direction.",synonyms:["aimless","random","haphazard","unfocused","erratic"],antonyms:["systematic","methodical","focused","purposeful"],confusedWith:[],tags:["behavior","planning"]},
  {word:"diatribe",partOfSpeech:"noun",definition:"a forceful and bitter verbal attack against someone or something",difficulty:2,mnemonic:"'DIE-A-TRIBE' — imagine someone so angry at a TRIBE they deliver a speech wishing them to DIE. An angry, bitter rant.",etymology:"Greek 'diatribe' = spending of time, discourse (dia- 'through' + tribein 'to rub, wear')",exampleSentence:"The senator launched into a diatribe against the proposed tax increases.",synonyms:["tirade","rant","harangue","invective","polemic"],antonyms:["praise","commendation","eulogy","tribute"],confusedWith:["dialect"],tags:["speech","anger"]},
  {word:"didactic",partOfSpeech:"adjective",definition:"intended to teach, particularly in having moral instruction as an ulterior motive; excessively instructive",difficulty:2,mnemonic:"'DID-ACTIC' — 'DID you learn the lesson?' Always teaching, sometimes annoyingly so. Like a teacher who never stops lecturing.",etymology:"Greek 'didaktikos' = skillful in teaching (from 'didaskein' = to teach)",exampleSentence:"The novel's didactic tone made it feel more like a lecture than a story.",synonyms:["instructive","educational","moralistic","pedagogic","preachy"],antonyms:["uninstructive","entertaining"],confusedWith:[],tags:["education","teaching"]},
  {word:"diffident",partOfSpeech:"adjective",definition:"modest or shy because of a lack of self-confidence",difficulty:2,mnemonic:"'DIFFI-DENT' — it's DIFFICULT for this person to be confiDENT. Shy and unsure of themselves.",etymology:"Latin 'diffidere' = to mistrust (dis- 'away, not' + fidere 'to trust')",exampleSentence:"Despite her remarkable talents, she was diffident about sharing her work with others.",synonyms:["shy","timid","bashful","reserved","self-effacing"],antonyms:["confident","bold","assertive","brash"],confusedWith:["different","indifferent"],tags:["personality","shyness"]},
  {word:"dilatory",partOfSpeech:"adjective",definition:"slow to act; intending to cause delay; procrastinating",difficulty:3,mnemonic:"'DELAY-TORY' — sounds like DELAY. A dilatory person is always DELAYing things. The king of procrastination.",etymology:"Latin 'dilatorius' = tending to delay (from 'dilator' = one who delays; 'differre' = to postpone)",exampleSentence:"The company's dilatory response to the complaint only frustrated the customers further.",synonyms:["slow","sluggish","tardy","procrastinating","unhurried"],antonyms:["prompt","swift","expeditious","punctual"],confusedWith:["dilute"],tags:["time","behavior"]},
  {word:"dirge",partOfSpeech:"noun",definition:"a lament for the dead, especially one forming part of a funeral rite; a mournful song",difficulty:2,mnemonic:"'D-URGE' — you feel the URGE to cry when you hear this sad song at a funeral. A DIRGE makes your heart heavy.",etymology:"Latin 'dirige' = 'direct!' (first word of the antiphon in the Office of the Dead: 'Dirige, Domine' = Direct, O Lord)",exampleSentence:"The mournful dirge echoed through the cathedral during the memorial service.",synonyms:["lament","elegy","requiem","threnody"],antonyms:["celebration","anthem","paean"],confusedWith:[],tags:["music","death"]},
  {word:"disabuse",partOfSpeech:"verb",definition:"to persuade someone that an idea or belief is mistaken; to free from a misconception",difficulty:2,mnemonic:"'DIS-ABUSE' — to stop the ABUSE of wrong thinking. You DIS (remove) the ABUSE (misuse) of false beliefs from someone's mind.",etymology:"French 'désabuser' (dés- 'away' + abuser 'to deceive')",exampleSentence:"Let me disabuse you of the notion that this project will be completed on time.",synonyms:["correct","enlighten","undeceive","set straight"],antonyms:["deceive","mislead","delude"],confusedWith:["abuse","misuse"],tags:["truth","correction"]},
  {word:"discerning",partOfSpeech:"adjective",definition:"having or showing good judgment; perceptive and discriminating in taste",difficulty:1,mnemonic:"'DIS-CERN-ING' — able to CERN (discern/separate) the good from the bad. A discerning eye picks out quality.",etymology:"Latin 'discernere' = to separate, distinguish (dis- 'apart' + cernere 'to separate, sift')",exampleSentence:"A discerning reader will notice the subtle irony throughout the author's prose.",synonyms:["perceptive","astute","judicious","shrewd","discriminating"],antonyms:["undiscriminating","obtuse","uncritical"],confusedWith:[],tags:["judgment","intelligence"]},
  {word:"dissonance",partOfSpeech:"noun",definition:"lack of harmony among musical notes; a tension or clash resulting from the combination of incompatible elements",difficulty:2,mnemonic:"'DIS-SONANCE' — DIS = not/bad, SONANCE = sound (like sonic). NOT-GOOD-SOUND. Discord in music or ideas.",etymology:"Latin 'dissonantia' = discord (dis- 'apart' + sonare 'to sound')",exampleSentence:"The dissonance between the company's stated values and its actual practices troubled many employees.",synonyms:["discord","conflict","incongruity","cacophony"],antonyms:["harmony","consonance","accord","concord"],confusedWith:["resonance"],tags:["conflict","music"]},
  {word:"dogmatic",partOfSpeech:"adjective",definition:"inclined to lay down principles as incontrovertibly true, without consideration of evidence or the opinions of others",difficulty:1,mnemonic:"'DOG-MATIC' — like a DOG with a bone who won't let go. Dogmatic people GRIP their beliefs and refuse to consider any other view.",etymology:"Greek 'dogmatikos' = pertaining to doctrines (from 'dogma' = opinion, belief; from 'dokein' = to seem, think)",exampleSentence:"His dogmatic insistence on traditional methods prevented the team from exploring innovative solutions.",synonyms:["opinionated","authoritarian","doctrinaire","rigid","inflexible"],antonyms:["open-minded","flexible","tolerant","receptive"],confusedWith:[],tags:["belief","rigidity"]},
  {word:"dubious",partOfSpeech:"adjective",definition:"hesitating or doubting; not to be relied upon; suspect",difficulty:1,mnemonic:"'DOUBT-IOUS' — full of DOUBT. If something is dubious, you DOUBT it. 'Hmm, that sounds dubious...'",etymology:"Latin 'dubiosus' = doubtful (from 'dubium' = doubt, from 'duo' = two — being 'of two minds')",exampleSentence:"The witness's dubious testimony cast doubt on the prosecution's entire case.",synonyms:["doubtful","questionable","suspect","uncertain","skeptical"],antonyms:["certain","trustworthy","reliable","undoubted"],confusedWith:[],tags:["doubt","judgment"]}
];
